/* eslint-disable react/prop-types */
import React, { useEffect, useState, useMemo } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
    Card,
    Stack,
    Button,
    Popover,
    MenuItem,
    Typography,
    IconButton,
    TablePagination,
} from '@mui/material';
import { axios } from '../../utils/axios';
import { updateUrlParams } from '../../utils/urlUtilis';
import Iconify from '../../components/iconify';
import Scrollbar from '../../components/scrollbar';
import { UserListToolbar } from '../../sections/@dashboard/user';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import useResponsive from '../../hooks/useResponsive';
import TanstackTable from '../../components/tanstackMUItable/TanstackTable';
import DateFormat from '../../components/dayjsFormat/DateFormat';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';

const ViewReview = () => {
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const navigate = useNavigate();
    const { i18 } = useMyContext();
    const [reviewsList, setReviewsList] = useState([]);
    const [opensDeleteModal, setOpensDeleteModal] = useState(false);
    const [totalCount, setTotalCount] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
    const [search, setsearch] = useState(queryParams.get('search') || '');
    const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
    const [filters, setFilters] = useState({ });
    const [isLoading, setIsLoading] = useState(true);

    const isMobile = useResponsive('down', 'sm')

    const fetchData = async () => {
        setIsLoading(true);
        try {
            // let url = `module/gallery/images?collection=listings?_page=${page}&_limit=${rowsPerPage}`
            let url = `module/admin/reviews?_page=${page}&_limit=${rowsPerPage}`

            // if (search) {
            //     url += `&search=${search}`;
            //     setPage(1);
            // }
            if (search) url += `&search=${search}`;
            Object.entries(filters).forEach(([key, value]) => {
                if (value) url += `&${key}=${value}`;
            });
            const response = await axios.get(url);
            if (response.status === 200) {
                setReviewsList(response?.data?.data?.reviewAndRating);
                setTotalCount(response?.data?.data?.totalCount ? response?.data?.data?.totalCount : 0);
            }
        } catch (error) {
            console.error(error);
        } finally {
            setIsLoading(false);
        }
    }

    useEffect(() => {
        fetchData();
    }, [page, rowsPerPage, search, filters]);

    useEffect(() => {
        updateUrlParams({ page, limit: rowsPerPage });
    }, [page, rowsPerPage, search]);

    const handleChangePage = (event, newPage) => {
        setPage(newPage + 1);
    };

    const handleChangeRowsPerPage = (event) => {
        const newLimit = parseInt(event.target.value, 10);
        setRowsPerPage(newLimit);
        setPage(1);
    };

    const ActionComponent = (cell) => {
        const original = cell?.row?.original;
        const value = cell?.getValue();
        const [anchorEl, setAnchorEl] = useState(null);
        const [menuRowId, setMenuRowId] = useState(null);

        const handleActionMenu = (event, rowId) => {
            setAnchorEl(event.currentTarget);
            setMenuRowId(rowId);
        };

        const handleActionMenuClose = () => {
            setAnchorEl(null);
            setMenuRowId(null);
        };

        const handleformdata = async (reviewIds) => {            
            navigate(`/dashboard/reviewAdminReplies?reviewIds=${reviewIds}`)
        };

        const deleteModal = (ids, reviewId) => {
            sessionStorage.setItem('rowListingIds', ids);
            sessionStorage.setItem('rowReviewIds', reviewId)
            setOpensDeleteModal(true);
        };

        return (
            <>
                <IconButton
                    sx={{
                        width: '37px',
                        height: '37px',
                        background: '#EBEBEB',
                        color: 'black',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        borderRadius: '50%',
                    }}
                    onClick={(event) => handleActionMenu(event, value)}
                >
                    <Iconify icon="mdi:dots-horizontal" />
                </IconButton>
                <Popover
                    anchorEl={anchorEl}
                    open={Boolean(anchorEl) && menuRowId === value}
                    onClose={handleActionMenuClose}
                    anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
                    transformOrigin={{ vertical: 'top', horizontal: 'right' }}
                    PaperProps={{
                        sx: { width: 140 },
                    }}
                >
                    <MenuItem onClick={() => handleformdata(original?.reviewId)}>
                        <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
                    </MenuItem>
                    <MenuItem onClick={() => deleteModal(original?._id, original?.reviewId)} sx={{ color: 'error.main' }}>
                        <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
                    </MenuItem>
                </Popover>
            </>
        )
    }

    const handleFilterByName = (event) => {
        const filterValue = event.target.value;
        setsearch(filterValue);
        queryParams.set('search', filterValue);
        window.history.pushState(null, '', `?${queryParams.toString()}`);
    };

    const columns = [
        {
            header: i18?.ACCOUNTSTITLE?.PROPERTYNAME || "Property Name",
            id: "propertyName",
            accessorKey: "propertyName",
            showFilter: true, 
            // cell: ({ cell: { value } }) => <span>{value}</span>
        },
        {
            header: i18?.ACCOUNTSTITLE?.PROPERTYCATEGORY || "Property Category",
            id: "propertyCategory",
            accessorKey: "propertyCategory",
            showFilter: true, 
            // cell: ({ cell: { value } }) => <span>{value}</span>
        },
        {
            header: i18?.ACCOUNTSTITLE?.PROVIDERNAME || "Provider Name",
            id: "providerName",
            accessorKey: "providerName",
            showFilter: true, 
            cell: ({ row }) => <span>{row?.original?.providerName || "---"}</span>
        },
        {
            header: i18?.ACCOUNTSTITLE?.REVIEWEDUSERNAME || "Reviewer's Name",
            id: "userName",
            accessorKey: "reviewedUserName",
            showFilter: true,
            cell: ({ row }) => <span>{row?.original?.reviewedUserName || "---"}</span>
        },
        {
            header: i18?.ACCOUNTSTITLE?.REVIEWS || "Reviews",
            id: "review",
            accessorKey: "review"
        },
        {
            header: i18?.ACCOUNTSTITLE?.DATEOFREVIEW || "Reviewed At",
            id: "dateOfReview",
            accessorKey: "dateOfReview",
            cell: ({ row }) => (
                <span>{DateFormat(row?.original?.dateOfReview)}</span>
            ),
        },
        {
            header: i18?.ACCOUNTSTITLE?.ACTION || "Action",
            id: "action",
            accessorKey: "action",
            cell: ActionComponent,
        }
    ];

    // const columns = useMemo(() => COLUMNS, []);
    // const data = React.useMemo(() => userList || [], [userList]);
    // const data = React.useMemo(() => reviewsList.map((reviews) => {
    //     return {
    //         propertyName: reviews?.propertyName,
    //         propertyCategory: reviews?.propertyCategory,
    //         providerName: reviews?.providerName,
    //         reviewedUserName: reviews?.reviewedUserName,
    //         review: reviews?.review,
    //         dateOfReview: reviews?.dateOfReview,
    //         action: reviews,
    //     }
    // }), [reviewsList]);

    const deleteUserReviews = async () => {
        const listingIds = sessionStorage.getItem('rowListingIds');

        const reviewIds = sessionStorage.getItem('rowReviewIds');
        
        try {
            const res = await axios.delete(`module/admin/reviews?listingId=${listingIds}&reviewId=${reviewIds}`);
            if (res.status === 200) {
                GenerateToastConfig(res.data.message, 'info');
                setOpensDeleteModal(false);
                fetchData();
            } else {
                GenerateToastConfig(res?.data?.message);
            }
        } catch (error) {
            GenerateToastConfig(error?.response?.data?.message);
        }
    };

    const handleFilterChange = (filterKey, value) => {
        setFilters((prev) => ({ ...prev, [filterKey]: value }));
        setPage(1);
      };

    return (
        <>
            <Helmet>
                <title> Review management | Admin panel </title>
            </Helmet>
            {isMobile && <Stack direction='row' alignItems="center" style={{ marginBottom: "30px" }} justifyContent="space-between">
                <Typography variant="h4" gutterBottom>
                    {i18?.ACCOUNTSTITLE?.REVIEWMANAGEMENT || "Review Management"}
                </Typography>
            </Stack>}
            {!isMobile && <Stack direction='row' alignItems="center" justifyContent="space-between">
                <Stack direction={'row'} alignItems="center" >
                    <Typography variant="h4" gutterBottom>
                        {i18?.ACCOUNTSTITLE?.REVIEWMANAGEMENT || "Review Management"}
                    </Typography>
                </Stack>
                <Stack direction='row' alignItems="center" >
                    <UserListToolbar
                        // numSelected={selected.length}
                        // filterName={filterName}
                        onFilterName={handleFilterByName}
                        search={search}
                        setsearch={setsearch}
                    />
                </Stack>
            </Stack>}

            <Card sx={{ padding: '0px 0px', margin: '0px 0px', overflowX: 'auto' }}>
                {isMobile && <UserListToolbar
                    // numSelected={selected.length}
                    // filterName={filterName}
                    onFilterName={handleFilterByName}
                    search={search}
                    setsearch={setsearch}
                />}

                <Scrollbar>
                    {/* <TanstackTable data={data} columns={columns} /> */}
                    <TanstackTableV8
                        data={reviewsList}
                        columns={columns}
                        filters={filters}
                        isLoading={isLoading}
                        onFilterChange={handleFilterChange}
                    />
                </Scrollbar>
            </Card>

            <TablePagination
                rowsPerPageOptions={[5, 10, 25]}
                component="div"
                count={totalCount || 0}
                rowsPerPage={rowsPerPage}
                page={page - 1}
                onPageChange={handleChangePage}
                onRowsPerPageChange={handleChangeRowsPerPage}
                sx={{
                    '.MuiTablePagination-selectLabel': {
                        marginTop: '12px',
                    },
                    '.MuiTablePagination-displayedRows': {
                        marginTop: '12px',
                    },
                    '.MuiTablePagination-actions': {
                        marginBottom: '6px',
                    }
                }}
            />

            <DeleteModal
                isDeleteOpen={opensDeleteModal}
                handleClose={() => setOpensDeleteModal(false)}
                handleDelete={deleteUserReviews}
            />
        </>
    )
}

export default ViewReview
